body.data:
{
  "aggregate": {{ this.params.collection }},
  "pipeline": {{
    (() => {
      const targetDomains = this.params.domains || [];
      const targetOrigins = this.params.origins || [];  
      const onlyWrong = this.params.onlyWrong === true || this.params.onlyWrong === "true";
      let matchConditions = {};

      if (Array.isArray(targetDomains) && targetDomains.length > 0) {
        matchConditions["domain"] = {
          "$in": targetDomains
        };
      }

      if (Array.isArray(targetOrigins) && targetOrigins.length > 0) {
        matchConditions["origin"] = {
          "$in": targetOrigins
        };
      }

      if (onlyWrong) {
        matchConditions["countWrong"] = { "$exists": true, "$gt": 0 };
      }

      let pipeline = [
        {
          "$match": matchConditions
        },
        {
          "$group": {
            "_id": "$countWrong",
            "errorCount": { "$first": "$countWrong" },
            "questionCount": { "$sum": 1 }
          }
        },
        {
          "$sort": { 
            "questionCount": -1 
          }
        },
        {
          "$project": {
            "_id": 0,
            "errorCount": 1,
            "questionCount": 1
          }
        }
      ];

      return pipeline;
    })()
  }},
  "cursor": {
    "batchSize": 10
  }
}

